input.old_string:
ITEMS=$(echo "$RECENTS" | jq '[.[] | {
  uid: .email,
  title: .email,
  subtitle: ("Last: " + .subject),
  arg: (.email + "||"),
  autocomplete: .email,
  icon: {path: "icon.png"}
}]')

input.new_string:
ITEMS=$(echo "$RECENTS" | jq '[.[] | {
  uid: .email,
  title: .email,
  subtitle: ("Last: " + .subject),
  valid: false,
  autocomplete: (.email + " "),
  icon: {path: "icon.png"}
}]')
